.geTabContainer {
	box-sizing: border-box;
	white-space: nowrap;
	overflow: hidden;
	padding: 0 20px 0 12px;
	display: flex;
	height: 32px;
	z-index: 1;
}

.geMinimal .geTabContainer .geZoomInput {
	margin-left: auto;
}

.geTabContainer .geZoomInput {
	margin: auto -16px auto 0;
	font-size: 12px;
	width: 56px;
}

.geTabScroller {
	display: inline-block;
	position: relative;
	white-space: nowrap;
	overflow: hidden;
	overflow-x: auto;
	margin: 0 8px;
	-ms-overflow-style: none;
	scrollbar-width: none;
	left: 0px;
}

.geTab .geButton {
	border-radius: 50%;
	margin-left: 0px;
}

.gePageTab:not(.geActivePage) .geButton {
	display: none;
}

.gePageTab:not(.geActivePage) {
	padding-right: 16px;
}

.gePageTab {
	padding: 0px 0px 0px 16px;
}

.geControlTab {
	width: 30px;
	margin: 0 4px;
}

.geTab {
	height: 100%;
	box-sizing: border-box;
	text-overflow: ellipsis;
	font-size: 13px;
	display: inline-flex;
	align-items: center;
	cursor: move;
}

.geSidebar {
	transform-origin: top left;
	padding: 4px 6px 8px 14px;
	overflow: hidden;
	white-space: normal;
}

.geEditor .geSearchSidebar {
	box-sizing: border-box;
	padding: 8px 4px 4px 4px;
	width: 100%;
}

.geTitle {
	display: flex;
	font-size: 13px;
	background-repeat: no-repeat;
	background-position: 2px 50%;
}

.geDarkMode div.mxRubberband {
	border-style: dashed;
}

.geEditor div.mxPopupMenu {
	box-shadow: 0px 0px 2px #C0C0C0;
	background-color: var(--ge-panel-color);
	background-image: none;
	border-radius: 4px;
	border-style: solid;
	border-width: 1px;
	border-color: lightgray;
	padding: 3px;
}

.geEditor div.mxPopupMenu.geToolbarMenu {
	border-radius: 10px;
	box-shadow: 0px 0px 3px 1px #d1d1d1;
	padding: 10px 14px 12px 14px;
	background-color: light-dark(var(--ge-panel-color), var(--ge-dark-panel-color));
}

.geToolbarMenu tr.mxPopupMenuItemHover {
	background-color: transparent !important;
}

.geToolbarMenu input[type="checkbox"] {
	margin: 0 6px 0 0;
}

.geToolbarMenu label {
	font-size: 13px;
}

.geSearchSidebar input {
	font-size: 12px;
	box-sizing: border-box;
	border-radius: 18px;
	width: 100%;
	outline: none;
	padding: 6px 20px 6px 10px
}

.geSearchSidebar>div {
	margin-bottom: 4px;
}

.geSearchSidebar>div>img.geAdaptiveAsset {
	position: relative;
	top: 4px;
	left: -24px;
	height: 16px;
	opacity: 0.75;
	cursor: pointer;
}

html table.mxPopupMenu {
	border-collapse: collapse;
	margin: 0px;
}

html td.mxPopupMenuItem {
	padding: 7px 30px 7px 30px;
	font-size: 10pt;
}

html td.mxPopupMenuIcon {
	background-color: transparent;
	padding: 0px;
}

table.mxPopupMenu tr {
	font-size: 4pt;
}

table.mxPopupMenu hr {
